#Requires -Version 5.1
# feat-rrhh-ficha-detalle.ps1
# Ficha de trabajador en modo lectura con dos pestanas.
#
# ARCHIVOS:
# 1. src/app/maestros/recursos-humanos/page.tsx (MODIFICADO)
#    - El nombre en la tabla es ahora un Link a /maestros/recursos-humanos/[id]
#    - Detecta ?edit=id en la URL y abre el modal de edicion directamente
#      (para que el boton Editar de la ficha funcione correctamente)
#    - Añadido useSearchParams y Link
#
# 2. src/app/maestros/recursos-humanos/[id]/page.tsx (NUEVO)
#    - Ruta: /maestros/recursos-humanos/[id]
#    - Pestaña DETALLE: foto, nombre, perfil, telefono, email, rol,
#      estado acceso, fecha inicio/fin (DD/MM/AAAA), asignable
#    - Pestaña ASIGNACIONES: tabla historica de obras con fecha inicio,
#      fecha fin, nombre de obra (link si tiene permiso ver obras),
#      estado de la obra. Ordenadas de mas reciente a mas antigua.
#      Query: asignaciones WHERE recurso_tipo=humano AND recurso_id=id
#      con join a obras y estados_obra. Solo carga al activar la pestaña.
#    - Permisos: maestros_rrhh.ver para ver la ficha,
#                maestros_rrhh.editar para ver el boton Editar,
#                obras.ver para ver los links de obra
#    - Sin acceso: redirige con mensaje
#    - Sin asignaciones: "Este trabajador todavia no tiene asignaciones registradas."

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> feat: ficha detalle RRHH" -ForegroundColor Cyan

Write-Host "  -> src\app\maestros\recursos-humanos\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx"), $bytes)
Write-Host "  OK: 21 KB" -ForegroundColor Green

Write-Host "  -> src\app\maestros\recursos-humanos\[id]\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\maestros\recursos-humanos\[id]\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\maestros\recursos-humanos\[id]\page.tsx"), $bytes)
Write-Host "  OK: 20 KB" -ForegroundColor Green

$ok1 = Test-Path (Join-Path $RepoPath "src\app\maestros\recursos-humanos\[id]\page.tsx")
$ok2 = (Get-Content (Join-Path $RepoPath "src\app\maestros\recursos-humanos\page.tsx") -Raw).Contains("href={\`/maestros/recursos-humanos/\${item.id}\`}")
$ok3 = (Get-Content (Join-Path $RepoPath "src\app\maestros\recursos-humanos\[id]\page.tsx") -Raw).Contains("asignaciones")
if ($ok1) { Write-Host "  OK: ruta [id] creada" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($ok2) { Write-Host "  OK: nombre es link al detalle" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($ok3) { Write-Host "  OK: pestaña asignaciones presente" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "feat: ficha detalle RRHH con pestanas Detalle y Asignaciones"'
Write-Host "  git push"
